def _decode(text):
    try:
        value = json.loads(text)
    except json.JSONDecodeError:
        import yaml

        try:
            value = yaml.safe_load(text)
        except yaml.YAMLError:
            raise ValueError("invalid rules syntax") from None
    if not isinstance(value, dict):
        raise TypeError("rules must contain a mapping")
    return value


@lru_cache(maxsize=1)
def _packaged_rules():
    resource = files("rtpipeline").joinpath("treatment_scope_rules_v1.yaml")
    return _decode(
        resource.read_text(encoding="utf-8") if resource.is_file() else _PACKAGED_JSON
    )


def load_rules(rules=None):
    """Return fresh packaged rules, or load an explicit JSON/YAML path or mapping."""
    if rules is None:
        return deepcopy(_packaged_rules())
    if isinstance(rules, (str, Path)):
        return _decode(Path(rules).read_text(encoding="utf-8"))
    if not isinstance(rules, dict):
        raise TypeError("rules must be a JSON/YAML path or mapping")
    return rules
